# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""FlagGems mixed_dtypes_linear implemented with Triton kernels.

Semantics (matches the original pytest reference):

    K = input.shape[-1]
    M = input.numel() // K
    N = scale.shape[0]
    ncols = weight.shape[1]                # weight is (K, ncols)
    int8 mode  : ncols == N,   q[k, n] = weight[k, n] - 128  (unsigned byte shift)
    int4 mode  : 2 * ncols == N, q[k, 2*j] = (w & 0xF) - 8, q[k, 2*j+1] = (w >> 4) - 8
    y[m, n] = sum_k input[m, k] * q[k, n]
    out     = activation(y * scale + bias)  in input.dtype

The reduction runs on the cube unit with fp32 accumulation.  The per-column
scale is loaded once per program (never inside the K loop).  For float16 it is
applied to the fp32 accumulator in the epilogue; for bfloat16 it must be folded
into the dequantized weights and rounded to bfloat16 before the dot, because
the reference's rounding boundary is observable through the strict bf16
tolerance.

The benchmark shapes divide evenly by the tile sizes, so EVEN_M/EVEN_N/EVEN_J
select unmasked loads and stores; the masked form is kept for the smaller
correctness shapes that do not divide.
"""

import torch
import triton
import triton.language as tl

_ACT_MAP = {"none": 0, None: 0, "relu": 1, "silu": 2}


@triton.jit
def _mixed_linear_int8_kernel(
    x_ptr,
    w_ptr,
    scale_ptr,
    bias_ptr,
    out_ptr,
    M,
    N,
    K,
    stride_xm,
    stride_wn,
    stride_om,
    HAS_BIAS: tl.constexpr,
    ACT: tl.constexpr,
    EPI_SCALE: tl.constexpr,
    EVEN_K: tl.constexpr,
    EVEN_M: tl.constexpr,
    EVEN_N: tl.constexpr,
    BM: tl.constexpr,
    BN: tl.constexpr,
    BK: tl.constexpr,
):
    pid = tl.program_id(0)
    num_pid_m = tl.cdiv(M, BM)
    # Consecutive programs share the same weight tile (pid_m fastest) so that
    # the dequantized tile is reused across M tiles through the cache.
    pid_m = pid % num_pid_m
    pid_n = pid // num_pid_m

    offs_m = pid_m * BM + tl.arange(0, BM)
    offs_n = pid_n * BN + tl.arange(0, BN)
    offs_k = tl.arange(0, BK)
    m_mask = offs_m < M
    n_mask = offs_n < N

    x_ptrs = x_ptr + offs_m[:, None] * stride_xm + offs_k[None, :]
    w_ptrs = w_ptr + offs_k[:, None] * stride_wn + offs_n[None, :]

    # Loop-invariant: one scale load per program instead of one per K step.
    if EVEN_N:
        s32 = tl.load(scale_ptr + offs_n).to(tl.float32)
    else:
        s32 = tl.load(scale_ptr + offs_n, mask=n_mask, other=0.0).to(tl.float32)

    acc = tl.zeros((BM, BN), dtype=tl.float32)
    for _k in range(0, tl.cdiv(K, BK)):
        if EVEN_K:
            if EVEN_M:
                a = tl.load(x_ptrs)
            else:
                a = tl.load(x_ptrs, mask=m_mask[:, None], other=0.0)
            if EVEN_N:
                wb = tl.load(w_ptrs)
            else:
                wb = tl.load(w_ptrs, mask=n_mask[None, :], other=0)
        else:
            k_mask = offs_k < K
            if EVEN_M:
                a = tl.load(x_ptrs, mask=k_mask[None, :], other=0.0)
            else:
                a = tl.load(x_ptrs, mask=m_mask[:, None] & k_mask[None, :], other=0.0)
            if EVEN_N:
                wb = tl.load(w_ptrs, mask=k_mask[:, None], other=0)
            else:
                wb = tl.load(w_ptrs, mask=k_mask[:, None] & n_mask[None, :], other=0)
        # Reference semantics: q = unsigned_byte - 128 (zero-point shift).
        # Masking with 0xFF keeps only the raw byte, so this is correct whether
        # the backend sign- or zero-extends the byte load.
        wi = (wb.to(tl.int32) & 0xFF) - 128
        if EPI_SCALE:
            wf = wi.to(tl.float32).to(a.dtype)
        else:
            wf = (wi.to(tl.float32) * s32[None, :]).to(a.dtype)
        acc = tl.dot(a, wf, acc)
        x_ptrs += BK
        w_ptrs += BK * stride_wn
        offs_k += BK

    if EPI_SCALE:
        acc = acc * s32[None, :]
    if HAS_BIAS:
        if EVEN_N:
            b = tl.load(bias_ptr + offs_n).to(tl.float32)
        else:
            b = tl.load(bias_ptr + offs_n, mask=n_mask, other=0.0).to(tl.float32)
        acc = acc + b[None, :]
    if ACT == 1:
        acc = tl.maximum(acc, 0.0)
    elif ACT == 2:
        acc = acc * tl.sigmoid(acc)

    out_ptrs = out_ptr + offs_m[:, None] * stride_om + offs_n[None, :]
    if EVEN_M and EVEN_N:
        tl.store(out_ptrs, acc.to(out_ptr.dtype.element_ty))
    else:
        tl.store(
            out_ptrs,
            acc.to(out_ptr.dtype.element_ty),
            mask=m_mask[:, None] & n_mask[None, :],
        )


@triton.jit
def _mixed_linear_int4_kernel(
    x_ptr,
    w_ptr,
    scale_ptr,
    bias_ptr,
    out_ptr,
    M,
    N,
    K,
    ncols,
    stride_xm,
    stride_wn,
    stride_om,
    HAS_BIAS: tl.constexpr,
    ACT: tl.constexpr,
    EPI_SCALE: tl.constexpr,
    EVEN_K: tl.constexpr,
    EVEN_M: tl.constexpr,
    EVEN_J: tl.constexpr,
    BM: tl.constexpr,
    BN: tl.constexpr,
    BK: tl.constexpr,
):
    # Two packed int4 values per byte: low nibble -> even output column,
    # high nibble -> odd output column.
    BNC: tl.constexpr = BN // 2
    pid = tl.program_id(0)
    num_pid_m = tl.cdiv(M, BM)
    pid_m = pid % num_pid_m
    pid_n = pid // num_pid_m

    offs_m = pid_m * BM + tl.arange(0, BM)
    offs_j = pid_n * BNC + tl.arange(0, BNC)
    offs_n = pid_n * BN + tl.arange(0, BN)
    offs_k = tl.arange(0, BK)
    m_mask = offs_m < M
    j_mask = offs_j < ncols
    n_mask = offs_n < N

    x_ptrs = x_ptr + offs_m[:, None] * stride_xm + offs_k[None, :]
    w_ptrs = w_ptr + offs_k[:, None] * stride_wn + offs_j[None, :]

    # Loop-invariant: two scale loads per program instead of two per K step.
    if EVEN_J:
        s_lo32 = tl.load(scale_ptr + 2 * offs_j).to(tl.float32)
        s_hi32 = tl.load(scale_ptr + 2 * offs_j + 1).to(tl.float32)
    else:
        s_lo32 = tl.load(scale_ptr + 2 * offs_j, mask=j_mask, other=0.0).to(tl.float32)
        s_hi32 = tl.load(scale_ptr + 2 * offs_j + 1, mask=j_mask, other=0.0).to(
            tl.float32
        )

    acc_lo = tl.zeros((BM, BNC), dtype=tl.float32)
    acc_hi = tl.zeros((BM, BNC), dtype=tl.float32)
    for _k in range(0, tl.cdiv(K, BK)):
        if EVEN_K:
            if EVEN_M:
                a = tl.load(x_ptrs)
            else:
                a = tl.load(x_ptrs, mask=m_mask[:, None], other=0.0)
            if EVEN_J:
                wb = tl.load(w_ptrs)
            else:
                wb = tl.load(w_ptrs, mask=j_mask[None, :], other=0)
        else:
            k_mask = offs_k < K
            if EVEN_M:
                a = tl.load(x_ptrs, mask=k_mask[None, :], other=0.0)
            else:
                a = tl.load(x_ptrs, mask=m_mask[:, None] & k_mask[None, :], other=0.0)
            if EVEN_J:
                wb = tl.load(w_ptrs, mask=k_mask[:, None], other=0)
            else:
                wb = tl.load(w_ptrs, mask=k_mask[:, None] & j_mask[None, :], other=0)
        u = wb.to(tl.int32)
        lo = (u & 0xF) - 8
        hi = ((u >> 4) & 0xF) - 8
        if EPI_SCALE:
            wlo = lo.to(tl.float32).to(a.dtype)
            whi = hi.to(tl.float32).to(a.dtype)
        else:
            wlo = (lo.to(tl.float32) * s_lo32[None, :]).to(a.dtype)
            whi = (hi.to(tl.float32) * s_hi32[None, :]).to(a.dtype)
        acc_lo = tl.dot(a, wlo, acc_lo)
        acc_hi = tl.dot(a, whi, acc_hi)
        x_ptrs += BK
        w_ptrs += BK * stride_wn
        offs_k += BK

    if EPI_SCALE:
        acc_lo = acc_lo * s_lo32[None, :]
        acc_hi = acc_hi * s_hi32[None, :]
    if HAS_BIAS:
        if EVEN_J:
            b_lo = tl.load(bias_ptr + 2 * offs_j).to(tl.float32)
            b_hi = tl.load(bias_ptr + 2 * offs_j + 1).to(tl.float32)
        else:
            b_lo = tl.load(bias_ptr + 2 * offs_j, mask=j_mask, other=0.0).to(tl.float32)
            b_hi = tl.load(bias_ptr + 2 * offs_j + 1, mask=j_mask, other=0.0).to(
                tl.float32
            )
        acc_lo = acc_lo + b_lo[None, :]
        acc_hi = acc_hi + b_hi[None, :]
    if ACT == 1:
        acc_lo = tl.maximum(acc_lo, 0.0)
        acc_hi = tl.maximum(acc_hi, 0.0)
    elif ACT == 2:
        acc_lo = acc_lo * tl.sigmoid(acc_lo)
        acc_hi = acc_hi * tl.sigmoid(acc_hi)

    out_tile = tl.interleave(acc_lo, acc_hi)
    out_ptrs = out_ptr + offs_m[:, None] * stride_om + offs_n[None, :]
    if EVEN_M and EVEN_J:
        tl.store(out_ptrs, out_tile.to(out_ptr.dtype.element_ty))
    else:
        tl.store(
            out_ptrs,
            out_tile.to(out_ptr.dtype.element_ty),
            mask=m_mask[:, None] & n_mask[None, :],
        )


def _pick_blocks(M, N, K, int4):
    # A taller M tile halves both the number of K iterations and the number of
    # passes over the weight matrix once M is large enough to fill it.  The
    # packed int4 kernel cannot use BM=64: its two half-width fp16 operands
    # plus int32 nibble temporaries exceed the unified buffer.
    if M <= 16:
        BM = 16
    elif M <= 32 or int4:
        BM = 32
    else:
        BM = 64
    BN = 128
    if N < 64:
        BN = 64
    # The K tile is limited by unified-buffer capacity: the int8 kernel keeps a
    # single fp16 weight tile, while the packed int4 kernel materialises two
    # half-width tiles plus their int32 nibble temporaries, so it can only
    # afford half the K tile.
    BK = 128 if int4 else 256
    return BM, BN, BK


def mixed_dtypes_linear(input, weight, scale, bias=None, activation=None):
    assert input.dtype in (
        torch.float16,
        torch.bfloat16,
    ), f"input must be float16 or bfloat16, got {input.dtype}"
    assert weight.dtype == torch.uint8, f"weight must be uint8, got {weight.dtype}"
    assert (
        scale.dtype == input.dtype
    ), f"scale dtype {scale.dtype} must match input dtype {input.dtype}"
    act = activation if activation is not None else "none"
    assert act in _ACT_MAP, f"unsupported activation: {activation}"

    orig = input.shape
    K = orig[-1]
    M = input.numel() // K
    N = scale.shape[0]
    ncols = weight.shape[1]
    assert ncols == N or 2 * ncols == N, (
        f"weight columns {ncols} must equal scale size {N} (int8) "
        f"or half of it (packed int4)"
    )
    int4 = ncols != N

    out = torch.empty((*orig[:-1], N), dtype=input.dtype, device=input.device)
    if M == 0 or N == 0:
        return out

    BM, BN, BK = _pick_blocks(M, N, K, int4)
    grid = (triton.cdiv(M, BM) * triton.cdiv(N, BN),)

    stride_xm = input.stride(-2) if input.dim() >= 2 else 1
    stride_wn = weight.stride(0)
    stride_om = out.stride(-2) if out.dim() >= 2 else N

    bias_arg = bias if bias is not None else scale
    epi_scale = input.dtype == torch.float16

    if int4:
        _mixed_linear_int4_kernel[grid](
            input,
            weight,
            scale,
            bias_arg,
            out,
            M,
            N,
            K,
            ncols,
            stride_xm,
            stride_wn,
            stride_om,
            HAS_BIAS=(bias is not None),
            ACT=_ACT_MAP[act],
            EPI_SCALE=epi_scale,
            EVEN_K=(K % BK == 0),
            EVEN_M=(M % BM == 0),
            EVEN_J=(ncols % (BN // 2) == 0),
            BM=BM,
            BN=BN,
            BK=BK,
            num_warps=8,
            num_stages=3,
        )
    else:
        _mixed_linear_int8_kernel[grid](
            input,
            weight,
            scale,
            bias_arg,
            out,
            M,
            N,
            K,
            stride_xm,
            stride_wn,
            stride_om,
            HAS_BIAS=(bias is not None),
            ACT=_ACT_MAP[act],
            EPI_SCALE=epi_scale,
            EVEN_K=(K % BK == 0),
            EVEN_M=(M % BM == 0),
            EVEN_N=(N % BN == 0),
            BM=BM,
            BN=BN,
            BK=BK,
            num_warps=8,
            num_stages=3,
        )
    return out
